  "Συνδεδεμένο ραντεβού": "clinical.linkedAppointmentSource",
  "Δεν υπάρχει καταγεγραμμένο επόμενο ραντεβού.": "clinical.noNextAppointmentAnswer",
  "Μπορώ να αναζητήσω ενεργή αγωγή, τελευταία ολοκληρωμένη επίσκεψη, επόμενο ραντεβού και εκκρεμότητες. Ρώτησε για ένα από αυτά.": "clinical.lookupHelp",
  "Μπορώ να βρω ενεργή αγωγή, ημερομηνία τελευταίας επίσκεψης, επόμενο ραντεβού και εκκρεμότητες. Δεν έχω ακόμη αναζήτηση μέσα σε κλινικές σημειώσεις.": "clinical.lookupLimits",
