  "Όλα τα κλινικά πεδία είναι προαιρετικά. Οι κλινικές σημειώσεις αποθηκεύονται χωρίς τελική καταχώριση όσο εργάζεστε. Η οριστικοποίηση κλείνει την καταγραφή και εντάσσει τις σημειώσεις στη σύνοψη του φακέλου. Οι αποθηκευμένες αλλαγές αγωγής και τα ραντεβού καταχωρίζονται άμεσα, ανεξάρτητα από την οριστικοποίηση.": "current.m045",
